package com.training.accounting.user; import jakarta.persistence.*;
@Entity @Table(name="app_users") public class AppUser { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="business_id",nullable=false) private Long businessId; @Column(nullable=false,unique=true) private String email; @Column(name="password_hash",nullable=false) private String passwordHash; @Column(nullable=false) private String role; @Column(nullable=false) private boolean active=true; public Long getId(){return id;} public Long getBusinessId(){return businessId;} public void setBusinessId(Long v){businessId=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }
